  const lx = clamp01(i.s.lx);
  const aq = clamp01(i.s.aq);
  const vtx = clamp01(i.s.vtx);
  const pxd = clamp01(i.s.pxd);
  const vigour = (0.6 + 0.4 * lx) * (0.6 + 0.4 * aq) * (0.9 + 0.1 * vtx);
