  for (let z = 0; z < n; z++) {
    const cz = (z + 0.5) * cellM;
    const row = z * n;
    for (let x = 0; x < n; x++) {
      const idx = row + x;
      const wetCell = (water[idx] ?? 0) > 0;
      const hm = height[idx] ?? 0;
