      const hx1 = x >= n - 1 ? hm : (height[idx + 1] ?? hm);
      const hz0 = z <= 0 ? hm : (height[idx - n] ?? hm);
      const hz1 = z >= n - 1 ? hm : (height[idx + n] ?? hm);
