      if (sl > 35) block[idx] = 1;
      const cx = (x + 0.5) * cellM;
      let best = 1e12;
      for (let m = 0; m < mc; m++) {
        const mdx = cx - (mx[m] ?? 0);
        const mdz = cz - (mz[m] ?? 0);
        const d2 = mdx * mdx + mdz * mdz;
        if (d2 < best) best = d2;
