  geometry.setAttribute('aTo', new THREE.BufferAttribute(to, 1));
  geometry.setAttribute('normal', new THREE.BufferAttribute(normal, 3));
  geometry.setAttribute('aNormalTo', new THREE.BufferAttribute(normalTo, 3));
